"""Align original/prepared/encoded first and corrected mixes without rerunning ASR."""
from pathlib import Path
import json,hashlib,math
import numpy as np,soundfile as sf
P=Path(__file__).resolve().parents[1];R=P.parents[1];L=P/'production/local';A=L/'audio-first-mix-preserved'
def read(p):return json.loads(p.read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 before=read(A/'audio-continuity.json');after=read(L/'audio-continuity.json');b=read(A/'audio-build.json');a=read(L/'audio-build.json')
 old,rate=sf.read(A/'narration-prepared-stem.wav',dtype='float32',always_2d=True);new,nrate=sf.read(L/'narration-prepared-stem.wav',dtype='float32',always_2d=True)
 assert old.shape==new.shape and rate==nrate==48000
 sourceold,rr=sf.read(A/'narration-source-timeline.wav',dtype='float32',always_2d=True);sourcenew,nn=sf.read(L/'narration-source-timeline.wav',dtype='float32',always_2d=True);assert np.array_equal(sourceold,sourcenew)
 mask=np.abs(old)>1e-5;ratios=new[mask].astype('float64')/old[mask].astype('float64');assert np.all(ratios>=-1e-5),'Phase/sign differences need timing review'
 gain=20*np.log10(np.maximum(ratios,1e-12));reduction=dict(minimumDb=float(gain.min()),p1Db=float(np.percentile(gain,1)),medianDb=float(np.median(gain)),p99Db=float(np.percentile(gain,99)),maximumDb=float(gain.max()),activeSamplesWithMoreThan3dBReductionShare=float(np.mean(gain<-3)),definition='Exact samplewise corrected-prepared/original-prepared ratio for abs(original)>1e-5; original gentle compressor is unchanged before the added compensated limiter.')
 prev={round(w['start'],5):w for w in before['speechActiveWindows']};rows=[]
 for cur in after['speechActiveWindows']:
  prior=prev[round(cur['start'],5)];assert abs(prior['sourceRmsDbfs']-cur['sourceRmsDbfs'])<1e-7
  rows.append(dict(start=cur['start'],end=cur['end'],originalPcmRmsDbfs=cur['sourceRmsDbfs'],beforePreparedRmsDbfs=prior['preparedRmsDbfs'],afterPreparedRmsDbfs=cur['preparedRmsDbfs'],limiterRmsGainDb=cur['preparedRmsDbfs']-prior['preparedRmsDbfs'],beforeVoiceRmsDbfs=prior['stemRmsDbfs'],afterVoiceRmsDbfs=cur['stemRmsDbfs'],beforeEncodedSpeechTransferDb=prior['encodedSpeechTransferDb'],afterEncodedSpeechTransferDb=cur['encodedSpeechTransferDb'],beforeSpeechToBackgroundDb=prior['speechToBackgroundDb'],afterSpeechToBackgroundDb=cur['speechToBackgroundDb']))
 out=dict(schemaVersion=1,status='aligned correction measured; contextual listening pending',sourceVoiceSha256=a['recipe']['voice']['sha256'],sourcePcmAndSampleCountUnchanged=True,captionInputsUnchanged=a['recipe']['frames']==b['recipe']['frames'],timeAlignment='Exact same frame/sample timeline; alimiter latency=true compensates its5mslookahead; no speech offset/speed/fade/duck change.',narrationPreparationBefore=b['narrationPreparation'],narrationPreparationAfter=a['narrationPreparation'],limiterSampleGain=reduction,beforeVoice=before['narrationStemMeasured'],afterVoice=after['narrationStemMeasured'],beforeFinal=before['finalEncodedMeasured'],afterFinal=after['finalEncodedMeasured'],sourceGameAndMusicRecipeUnchanged={k:a['recipe'][k]==b['recipe'][k] for k in ['voice','sources','music','gameSections','durationSeconds','frames']},windowSeconds=.4,stepSeconds=.1,allAlignedSpeechWindows=rows,beforeJoins=before['joins'],afterJoins=after['joins'],beforeSustainedMaskingSeconds=sum(x['consecutiveMeasurementSeconds'] for x in before['sustainedMaskingCandidates']),afterSustainedMaskingSeconds=sum(x['consecutiveMeasurementSeconds'] for x in after['sustainedMaskingCandidates']),encodedAttenuationCandidates=after['sustainedEncodedAttenuationCandidates'],remainingLowLevelRanges=after['sustainedSourceLowLevelCandidates'],remainingMaskingRanges=after['sustainedMaskingCandidates'],listeningContexts=after['contextPlaybackRequiredRanges'],humanListening='pending',wordWorldHumanCheck=[10.42,10.84],fullVoiceAsrRepeated=False,fullFinalAsrRuns='one current mix run is in progress or completed; independent report',fingerprints={'firstMix':b['fingerprint'],'correctedMix':a['fingerprint'],'firstReportSha256':sha(A/'audio-continuity.json'),'correctedReportSha256':sha(L/'audio-continuity.json')})
 (L/'audio-before-after.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf8');print(json.dumps({k:out[k] for k in ['status','limiterSampleGain','beforeSustainedMaskingSeconds','afterSustainedMaskingSeconds','encodedAttenuationCandidates']},ensure_ascii=False))
if __name__=='__main__':main()
